                break;
              }
            }
            if (myEntry) {
              currentPhaseKey = msg.phase_key;
              currentFinished = true;
              if (typeof msg.state_version === "number" && msg.state_version > currentStateVersion) {
                currentStateVersion = msg.state_version;
                container.dataset.stateVersion = String(currentStateVersion);
              }
              currentViewKey =
                "finished:" + currentPlayerId + ":" + myEntry.place + ":" +
                msg.leaderboard.length + ":" + myEntry.points + ":" +
                Boolean(myEntry.winner) + ":" + currentStateVersion;
              container.dataset.phaseKey = currentPhaseKey;
              container.dataset.viewKey = currentViewKey;
              container.dataset.finished = "true";
              container.innerHTML = buildFinishedPlayerHtml(
                currentPlayerName,
                myEntry.place,
                msg.leaderboard.length,
                myEntry.points,
                Boolean(myEntry.winner)
              );
              return;
            }
          }
        }
        if (msg.phase_key && msg.phase_key !== currentPhaseKey) {
          fetchPlayerState(true);
        }
      },
      function () {
        fetchPlayerState(true);
      }
    );

    setInterval(function () { fetchPlayerState(false); }, 150);
  }

  function boot() {
    var modEl = document.querySelector("[data-live-moderator-game]");
    if (modEl) initModeratorGame(modEl);

    var playEl = document.querySelector("[data-live-player-game]");
    if (playEl) initPlayerGame(playEl);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
