          "X-Requested-With": "XMLHttpRequest"
        },
        body: new FormData(form),
        credentials: "same-origin"
      })
        .then(function (res) { return res.ok ? res.json() : null; })
        .then(function (data) {
          submittingAction = Math.max(0, submittingAction - 1);
          if (data) applyModeratorState(data, true);
        })
        .catch(function () {
          submittingAction = Math.max(0, submittingAction - 1);
          fetchModeratorState(true);
        });
    });

    connectGameCable(
